def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances = {}
    frozen = set()
    history = []
    rejected = []

    def parse_amount(token):
        if not token or any(ch < "0" or ch > "9" for ch in token):
            return None
        # Parse in small chunks to support amounts of any length.
        value = 0
        for start in range(0, len(token), 9):
            chunk = token[start:start + 9]
            value = value * (10 ** len(chunk)) + int(chunk)
        return value

    for index, operation in enumerate(ops):
        tokens = operation.split(" ")
        verb = tokens[0]
        success = False

        if verb == "undo" and len(tokens) == 1:
            if history:
                action = history.pop()
                kind = action[0]

                if kind == "open":
                    del balances[action[1]]
                    frozen.discard(action[1])
                elif kind == "deposit":
                    balances[action[1]] -= action[2]
                elif kind == "withdraw":
                    balances[action[1]] += action[2]
                elif kind == "transfer":
                    balances[action[1]] += action[3]
                    balances[action[2]] -= action[3]
                elif kind == "freeze":
                    frozen.remove(action[1])
                else:
                    frozen.add(action[1])
                success = True

        elif verb in ("open", "deposit", "withdraw") and len(tokens) == 3:
            account, amount_token = tokens[1], tokens[2]
            amount = parse_amount(amount_token)

            if account and amount is not None:
                if verb == "open" and account not in balances:
                    balances[account] = amount
                    history.append(("open", account))
                    success = True
                elif verb == "deposit" and amount > 0 and account in balances:
                    balances[account] += amount
                    history.append(("deposit", account, amount))
                    success = True
                elif (
                    verb == "withdraw"
                    and amount > 0
                    and account in balances
                    and account not in frozen
                    and balances[account] >= amount
                ):
                    balances[account] -= amount
                    history.append(("withdraw", account, amount))
                    success = True

        elif verb == "transfer" and len(tokens) == 4:
            source, target, amount_token = tokens[1], tokens[2], tokens[3]
            amount = parse_amount(amount_token)

            if (
                source
                and target
                and amount is not None
                and amount > 0
                and source != target
                and source in balances
                and target in balances
                and source not in frozen
                and balances[source] >= amount
            ):
                balances[source] -= amount
                balances[target] += amount
                history.append(("transfer", source, target, amount))
                success = True

        elif verb in ("freeze", "unfreeze") and len(tokens) == 2:
            account = tokens[1]
            if account in balances:
                if verb == "freeze" and account not in frozen:
                    frozen.add(account)
                    history.append(("freeze", account))
                    success = True
                elif verb == "unfreeze" and account in frozen:
                    frozen.remove(account)
                    history.append(("unfreeze", account))
                    success = True

        if not success:
            rejected.append(index)

    return balances, rejected
